def norm(p): return p.read_text(encoding='utf-8-sig').replace('\r\n','\n')
changes=[]
for rel,content in FILES.items():
 p=ROOT/rel
 if p.exists():
  existing=norm(p)
  if existing==content: continue
  if rel not in BASELINE or existing!=BASELINE[rel]:
   sys.exit('CONFLICT: file differs from expected Wave 1 baseline: '+rel)
 changes.append((p,content))
if not changes:
 print('ALREADY APPLIED: Wave 1 reconciliation and Wave 2 unchanged');sys.exit(0)
for p,content in changes:
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8',newline='\n')
print('SUCCESS: Wave 1 reconciled; Wave 2 candidate IDs 0006-0010 integrated; no hardware testing')
